@startuml
skinparam monochrome true

state "Bereit" as bereit {
  [*] --> bereit : start
}

state "Fehler" as fehler {
  accept event "notaus"
  :Notfallmodus aktiviert/
  :Alle Funktionen deaktiviert/
}

state "Waschprogramm" as waschprogramm {
  [*] --> waschprogramm : startDrücken
  state "WasserEinlassen" as wasser {
    :Wasser einlassen/
    :Trommel füllen/
  }
  state "Waschen" as waschen {
    :Waschmittel dosieren/
    :Temperatur regulieren/
    :Trommel drehen/
  }
  state "Schleudern" as schleudern {
    :Wasser abpumpen/
    :Trommel schnell drehen/
  }

  wasser --> waschen : Zeit abgelaufen
  waschen --> schleudern : Zeit abgelaufen
  schleudern --> waschprogramm : Fertig
}

state "Fertig" as fertig {
  :piepen() : entry
  :Tür entriegelt/
  :Licht aus/
  :Tür öffnen möglich/
  fertig --> bereit : türÖffnen
}

bereit --> waschprogramm : startDrücken
waschprogramm --> fertig : Fertig
fehler --> bereit : Reset
fehler --> waschprogramm : Reset
fehler --> fertig : Reset

alt Fehlerfall
  bereit --> fehler : notaus
  waschprogramm --> fehler : notaus
  fertig --> fehler : notaus
end

hide footbox
@enduml

