```
@startuml
abstract class Person {
  + String name
  + String email
  + {abstract} void berechneRabatt(): double
}

class Kunde {
  - String kundenId
  - String adresse
  + double berechneRabatt(): double
}

class Mitarbeiter {
  - String mitarbeiterId
  - String abteilung
  + void arbeitszeitenEintragen(): void
}

class Artikel {
  - String artikelId
  - String name
  - double preis
  - int lagerbestand
  + void bestandsupdate(int menge): void
}

class Warenkorb {
  - String korbid
  - double gesamtpreis
  + void artikelHinzufuegen(Artikel art, int menge): void
  + void artikelEntfernen(String artikelId): void
}

class WarenkorbPosition {
  - Artikel artikel
  - int menge
  - double positionspreis
}

class Bestellung {
  - String bestellnummer
  - Date datum
  - Status status
  enum Status {
    ERSTELLT
    BEARBEITET
    VERSANDT
    ABGESCHLOSSEN
  }
  + void statusAktualisieren(Status neuerStatus): void
}

class Rechnung {
  - String rechnungsnummer
  - Date erstelldatum
  - double steuerbetrag
  + void drucken(): void
}

Kunde "1" *-- "1" Warenkorb : enthält
Warenkorb o-- "0..*" WarenkorbPosition : besteht aus
WarenkorbPosition "1" --> "1" Artikel : referenziert
Bestellung "1" -- "1" Rechnung : generiert
Bestellung "1" -- "1" Warenkorb : basierend auf
@enduml
```

